class Solution:
    def countBalancedIntegers(self, low: int, high: int) -> int:
        from functools import lru_cache
        def f(x: int) -> int:
            if x <= 0:
                return 0
            ds = str(x)
            n = len(ds)
            @lru_cache(None)
            def dp(pos, diff, started, tight):
                if pos == n:
                    return 1 if (started and diff == 0) else 0
                hi = int(ds[pos]) if tight else 9
                res = 0
                for d in range(hi + 1):
                    nt = tight and d == hi
                    if started:
                        res += dp(pos + 1, diff + (d if pos % 2 == 0 else -d), 1, nt)
                    elif d == 0:
                        res += dp(pos + 1, 0, 0, nt)
                    else:
                        res += dp(pos + 1, d, 1, nt)
                return res
            return dp(0, 0, 0, True)
        return f(high) - f(low - 1)

