class Solution {
public:
    long long countBalancedIntegers(int low, int high) {
        auto f = [](long long x) -> long long {
            if (x <= 0) return 0;
            string ds = to_string(x);
            int n = ds.size();
            static long long memo[20][300][2][2];
            static string cur;
            cur = ds;
            memset(memo, -1, sizeof(memo));
            function<long long(int,int,int,int)> dp = [&](int pos, int diff, int started, int tight) -> long long {
                if (pos == n) return (started && diff == 0) ? 1 : 0;
                long long &m = memo[pos][diff + 150][started][tight];
                if (m != -1) return m;
                int hi = tight ? cur[pos] - '0' : 9;
                long long res = 0;
                for (int d = 0; d <= hi; d++) {
                    int nt = (tight && d == hi) ? 1 : 0;
                    if (started) res += dp(pos + 1, diff + (pos % 2 == 0 ? d : -d), 1, nt);
                    else if (d == 0) res += dp(pos + 1, 0, 0, nt);
                    else res += dp(pos + 1, d, 1, nt);
                }
                return m = res;
            };
            return dp(0, 0, 0, 1);
        };
        return f(high) - f((long long)low - 1);
    }
};

