class Solution {
    private String ds;
    private Long[][][][] memo;
    public long countBalancedIntegers(int low, int high) {
        return f(high) - f((long) low - 1);
    }
    private long f(long x) {
        if (x <= 0) return 0;
        ds = Long.toString(x);
        int n = ds.length();
        memo = new Long[n + 1][300][2][2];
        return dp(0, 0, 0, 1);
    }
    private long dp(int pos, int diff, int started, int tight) {
        if (pos == ds.length()) return (started == 1 && diff == 0) ? 1 : 0;
        if (memo[pos][diff + 150][started][tight] != null) return memo[pos][diff + 150][started][tight];
        int hi = tight == 1 ? ds.charAt(pos) - '0' : 9;
        long res = 0;
        for (int d = 0; d <= hi; d++) {
            int nt = (tight == 1 && d == hi) ? 1 : 0;
            if (started == 1) res += dp(pos + 1, diff + (pos % 2 == 0 ? d : -d), 1, nt);
            else if (d == 0) res += dp(pos + 1, 0, 0, nt);
            else res += dp(pos + 1, d, 1, nt);
        }
        memo[pos][diff + 150][started][tight] = res;
        return res;
    }
}

