var countBalancedIntegers = function(low, high) {
    function f(x) {
        if (x <= 0) return 0;
        const ds = String(x);
        const n = ds.length;
        const memo = new Map();
        function dp(pos, diff, started, tight) {
            if (pos === n) return (started && diff === 0) ? 1 : 0;
            const key = pos + ',' + diff + ',' + started + ',' + tight;
            if (memo.has(key)) return memo.get(key);
            const hi = tight ? +ds[pos] : 9;
            let res = 0;
            for (let d = 0; d <= hi; d++) {
                const nt = tight && d === hi ? 1 : 0;
                if (started) res += dp(pos + 1, diff + (pos % 2 === 0 ? d : -d), 1, nt);
                else if (d === 0) res += dp(pos + 1, 0, 0, nt);
                else res += dp(pos + 1, d, 1, nt);
            }
            memo.set(key, res);
            return res;
        }
        return dp(0, 0, 0, 1);
    }
    return f(high) - f(low - 1);
};
